-- Exercise library: barbell / dumbbell twins and lifts from imported plans that had no match.
-- Mirrors scripts/catalog-data.mjs (also in the regenerated catalog seed). Data only, safe to re-run.
-- Ids stay the same, so plans and logged history are untouched; only names, new rows and tags change.
-- 29 exercises: Barbell_Deadlift, Barbell_Squat, Barbell_Step_Ups, Barbell_Walking_Lunge, Bent-Arm_Barbell_Pullover, Cable_Crossover, Cable_One_Arm_Tricep_Extension, Dumbbell_Bicep_Curl, Dumbbell_Rear_Lunge, Face_Pull, Front_Dumbbell_Raise, Palms-Up_Barbell_Wrist_Curl_Over_A_Bench, Reverse_Barbell_Curl, Side_Lateral_Raise, Standing_Barbell_Calf_Raise, Standing_Dumbbell_Reverse_Curl, Standing_Dumbbell_Upright_Row, Standing_Military_Press, Upright_Barbell_Row, Bulgarian_Split_Squat, Dumbbell_Deadlift, Dumbbell_Walking_Lunge, Barbell_Reverse_Lunge, Barbell_Split_Squat, Barbell_Bulgarian_Split_Squat, Dumbbell_Single_Leg_Romanian_Deadlift, Barbell_Front_Raise, Assisted_Dip, Single_Leg_Lying_Leg_Curl

on conflict (id) do update set name = excluded.name, aliases = excluded.aliases, category = excluded.category,
  movement_pattern = excluded.movement_pattern, mechanic = excluded.mechanic, force = excluded.force, level = excluded.level,
  instructions = excluded.instructions, images = excluded.images, is_common = excluded.is_common,
  is_active = excluded.is_active, source = excluded.source;

delete from public.exercise_muscles where exercise_id in ('Barbell_Deadlift', 'Barbell_Squat', 'Barbell_Step_Ups', 'Barbell_Walking_Lunge', 'Bent-Arm_Barbell_Pullover', 'Cable_Crossover', 'Cable_One_Arm_Tricep_Extension', 'Dumbbell_Bicep_Curl', 'Dumbbell_Rear_Lunge', 'Face_Pull', 'Front_Dumbbell_Raise', 'Palms-Up_Barbell_Wrist_Curl_Over_A_Bench', 'Reverse_Barbell_Curl', 'Side_Lateral_Raise', 'Standing_Barbell_Calf_Raise', 'Standing_Dumbbell_Reverse_Curl', 'Standing_Dumbbell_Upright_Row', 'Standing_Military_Press', 'Upright_Barbell_Row', 'Bulgarian_Split_Squat', 'Dumbbell_Deadlift', 'Dumbbell_Walking_Lunge', 'Barbell_Reverse_Lunge', 'Barbell_Split_Squat', 'Barbell_Bulgarian_Split_Squat', 'Dumbbell_Single_Leg_Romanian_Deadlift', 'Barbell_Front_Raise', 'Assisted_Dip', 'Single_Leg_Lying_Leg_Curl');
delete from public.exercise_equipment where exercise_id in ('Barbell_Deadlift', 'Barbell_Squat', 'Barbell_Step_Ups', 'Barbell_Walking_Lunge', 'Bent-Arm_Barbell_Pullover', 'Cable_Crossover', 'Cable_One_Arm_Tricep_Extension', 'Dumbbell_Bicep_Curl', 'Dumbbell_Rear_Lunge', 'Face_Pull', 'Front_Dumbbell_Raise', 'Palms-Up_Barbell_Wrist_Curl_Over_A_Bench', 'Reverse_Barbell_Curl', 'Side_Lateral_Raise', 'Standing_Barbell_Calf_Raise', 'Standing_Dumbbell_Reverse_Curl', 'Standing_Dumbbell_Upright_Row', 'Standing_Military_Press', 'Upright_Barbell_Row', 'Bulgarian_Split_Squat', 'Dumbbell_Deadlift', 'Dumbbell_Walking_Lunge', 'Barbell_Reverse_Lunge', 'Barbell_Split_Squat', 'Barbell_Bulgarian_Split_Squat', 'Dumbbell_Single_Leg_Romanian_Deadlift', 'Barbell_Front_Raise', 'Assisted_Dip', 'Single_Leg_Lying_Leg_Curl');


