insert into public.exercises (id, name, aliases, category, movement_pattern, mechanic, force, level, instructions, images, is_common, is_active, source) values
  ('Barbell_Deadlift', 'Deadlift', array['Barbell Deadlift', 'Conventional Deadlift']::text[], 'strength', 'hinge', 'compound', 'pull', 'intermediate', array['Stand in front of a loaded barbell.', 'While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.', 'While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.', 'Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.', 'Perform the amount of repetitions prescribed in the program.']::text[], array['Barbell_Deadlift/0.jpg', 'Barbell_Deadlift/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Barbell_Squat', 'Back Squat', array['Barbell Squat', 'Barbell Back Squat']::text[], 'strength', 'squat', 'compound', 'push', 'beginner', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], array['Barbell_Squat/0.jpg', 'Barbell_Squat/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Barbell_Step_Ups', 'Barbell Step-Up', array['Barbell Step Ups']::text[], 'strength', 'lunge', 'compound', 'push', 'intermediate', array['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position.', 'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.', 'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.', 'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[], array['Barbell_Step_Ups/0.jpg', 'Barbell_Step_Ups/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Barbell_Walking_Lunge', 'Barbell Walking Lunge', '{}'::text[], 'strength', 'lunge', 'compound', 'push', 'beginner', array['Begin standing with your feet shoulder width apart and a barbell across your upper back.', 'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.', 'Drive through the heel of your lead foot and extend both knees to raise yourself back up.', 'Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[], array['Barbell_Walking_Lunge/0.jpg', 'Barbell_Walking_Lunge/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Bent-Arm_Barbell_Pullover', 'Barbell Pullover', array['Bent-Arm Barbell Pullover']::text[], 'strength', 'other', 'compound', 'pull', 'intermediate', array['Lie on a flat bench with a barbell using a shoulder grip width.', 'Hold the bar straight over your chest with a bend in your arms. This will be your starting position.', 'While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.', 'At that point, bring the barbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.', 'Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[], array['Bent-Arm_Barbell_Pullover/0.jpg', 'Bent-Arm_Barbell_Pullover/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Cable_Crossover', 'Cable Crossover', array['Cable Fly', 'Standing Cable Fly', 'Cable Chest Fly']::text[], 'strength', 'isolation', 'isolation', 'push', 'beginner', array['To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.', 'Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions.']::text[], array['Cable_Crossover/0.jpg', 'Cable_Crossover/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Cable_One_Arm_Tricep_Extension', 'Single-Arm Cable Extension', array['Cable One Arm Tricep Extension', 'Single-Arm Rope Pushdown', 'Single-Arm Tricep Pushdown', 'Single-Arm Cable Pushdown']::text[], 'strength', 'isolation', 'isolation', 'push', 'beginner', array['With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.', 'Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position.', 'As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement. Tip: Only the forearms should move. Your upper arms should remain stationary at all times.', 'Squeeze the triceps and hold for a second in this contracted position.', 'Slowly return the handle to the starting position.', 'Repeat for the recommended amount of repetitions and then perform the same movement with the other arm.']::text[], array['Cable_One_Arm_Tricep_Extension/0.jpg', 'Cable_One_Arm_Tricep_Extension/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Dumbbell_Bicep_Curl', 'Dumbbell Curl', array['Dumbbell Bicep Curl', 'Dumbbell Supinated Curl', 'Supinated Dumbbell Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.', 'Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.', 'Then, inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], array['Dumbbell_Bicep_Curl/0.jpg', 'Dumbbell_Bicep_Curl/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Dumbbell_Rear_Lunge', 'Dumbbell Reverse Lunge', array['Dumbbell Rear Lunge']::text[], 'strength', 'lunge', 'compound', 'push', 'intermediate', array['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.', 'Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.', 'Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.', 'Now repeat with the opposite leg.']::text[], array['Dumbbell_Rear_Lunge/0.jpg', 'Dumbbell_Rear_Lunge/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Face_Pull', 'Face Pull', array['Seated Face Pull', 'Rope Face Pull', 'Cable Face Pull']::text[], 'strength', 'other', 'compound', 'pull', 'intermediate', array['Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground.']::text[], array['Face_Pull/0.jpg', 'Face_Pull/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Front_Dumbbell_Raise', 'Dumbbell Front Raise', array['Front Dumbbell Raise']::text[], 'strength', 'isolation', 'isolation', 'push', 'beginner', array['Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.', 'Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.', 'Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm.']::text[], array['Front_Dumbbell_Raise/0.jpg', 'Front_Dumbbell_Raise/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Palms-Up_Barbell_Wrist_Curl_Over_A_Bench', 'Barbell Wrist Curl', array['Palms-Up Barbell Wrist Curl Over A Bench']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Start out by placing a barbell on one side of a flat bench.', 'Kneel down on both of your knees so that your body is facing the flat bench.', 'Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling.', 'Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.']::text[], array['Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg', 'Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Reverse_Barbell_Curl', 'Barbell Reverse Curl', array['Reverse Barbell Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Stand up with your torso upright while holding a barbell at shoulder width with the elbows close to the torso. The palm of your hands should be facing down (pronated grip). This will be your starting position.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], array['Reverse_Barbell_Curl/0.jpg', 'Reverse_Barbell_Curl/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Side_Lateral_Raise', 'Lateral Raise', array['Side Lateral Raise', 'Dumbbell Lateral Raise', 'Dumbbell Side Lateral Raise']::text[], 'strength', 'isolation', 'isolation', 'push', 'beginner', array['Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.', 'While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.', 'Lower the dumbbells back down slowly to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], array['Side_Lateral_Raise/0.jpg', 'Side_Lateral_Raise/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Standing_Barbell_Calf_Raise', 'Barbell Calf Raise', array['Standing Barbell Calf Raise']::text[], 'strength', 'isolation', 'isolation', 'push', 'beginner', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the bar on the back of your shoulders (slightly below the neck).', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: For better range of motion you may also place the ball of your feet on a wooden block but be careful as this option requires more balance and a sturdy block.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[], array['Standing_Barbell_Calf_Raise/0.jpg', 'Standing_Barbell_Calf_Raise/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Standing_Dumbbell_Reverse_Curl', 'Dumbbell Reverse Curl', array['Standing Dumbbell Reverse Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'intermediate', array['To begin, stand straight with a dumbbell in each hand using a pronated grip (palms facing down). Your arms should be fully extended while your feet are shoulder width apart from each other. This is the starting position.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the muscle.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], array['Standing_Dumbbell_Reverse_Curl/0.jpg', 'Standing_Dumbbell_Reverse_Curl/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Standing_Dumbbell_Upright_Row', 'Dumbbell Upright Row', array['Standing Dumbbell Upright Row']::text[], 'strength', 'other', 'compound', 'pull', 'beginner', array['Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it up and the elbows should drive the motion. Continue to lift them until they nearly touch your chin. Tip: Your elbows should drive the motion. As you lift the dumbbells, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], array['Standing_Dumbbell_Upright_Row/0.jpg', 'Standing_Dumbbell_Upright_Row/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Standing_Military_Press', 'Overhead Press', array['Standing Military Press', 'Military Press', 'Barbell Overhead Press']::text[], 'strength', 'vertical_push', 'compound', 'push', 'beginner', array['Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.', 'Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.', 'Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the collarbone slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.']::text[], array['Standing_Military_Press/0.jpg', 'Standing_Military_Press/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Upright_Barbell_Row', 'Barbell Upright Row', array['Upright Barbell Row']::text[], 'strength', 'other', 'compound', 'pull', 'beginner', array['Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position.', 'Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should drive the motion, and should always be higher than your forearms. Remember to keep your torso stationary and pause for a second at the top of the movement.', 'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], array['Upright_Barbell_Row/0.jpg', 'Upright_Barbell_Row/1.jpg']::text[], true, true, 'free-exercise-db'),
  ('Bulgarian_Split_Squat', 'Dumbbell Bulgarian Split Squat', '{}'::text[], 'strength', 'lunge', 'compound', 'push', 'intermediate', array['Stand a stride in front of a bench and rest the top of your back foot on it.', 'Hold the weights at your sides and lower straight down until your front thigh is about parallel.', 'Drive through the front foot to stand back up. Finish all reps, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dumbbell_Deadlift', 'Dumbbell Deadlift', '{}'::text[], 'strength', 'hinge', 'compound', 'pull', 'beginner', array['Stand with a dumbbell on the floor outside each foot.', 'Hinge at the hips and bend your knees to grip the handles with a flat back and chest up.', 'Drive through your feet to stand tall, squeezing your glutes, then lower the weights back down the same way.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dumbbell_Walking_Lunge', 'Dumbbell Walking Lunge', '{}'::text[], 'strength', 'lunge', 'compound', 'push', 'beginner', array['Stand tall with a dumbbell in each hand at your sides.', 'Step forward and lower until your back knee nearly touches the floor.', 'Push through the front foot and bring the back foot through into the next step. Count each leg.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Barbell_Reverse_Lunge', 'Barbell Reverse Lunge', '{}'::text[], 'strength', 'lunge', 'compound', 'push', 'intermediate', array['Unrack the bar onto your upper back and stand tall.', 'Step one foot back and lower until your back knee nearly touches the floor.', 'Drive through the front foot to step back to standing. Alternate legs or finish one side first.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Barbell_Split_Squat', 'Barbell Split Squat', '{}'::text[], 'strength', 'lunge', 'compound', 'push', 'intermediate', array['Unrack the bar onto your upper back and take a long split stance.', 'Lower straight down until your back knee nearly touches the floor.', 'Drive back up through the front foot. Finish all reps, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Barbell_Bulgarian_Split_Squat', 'Barbell Bulgarian Split Squat', '{}'::text[], 'strength', 'lunge', 'compound', 'push', 'intermediate', array['Unrack the bar onto your upper back and rest the top of your back foot on a bench behind you.', 'Lower straight down until your front thigh is about parallel.', 'Drive through the front foot to stand back up. Finish all reps, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dumbbell_Single_Leg_Romanian_Deadlift', 'Single-Leg Dumbbell RDL', '{}'::text[], 'strength', 'hinge', 'compound', 'pull', 'intermediate', array['Hold a dumbbell in the hand opposite your standing leg.', 'Hinge forward and let the free leg reach back until your body is close to level, back flat.', 'Squeeze the glute of the standing leg to return to tall. Finish all reps, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Barbell_Front_Raise', 'Barbell Front Raise', '{}'::text[], 'strength', 'isolation', 'isolation', 'push', 'beginner', array['Hold the bar in front of your thighs with an overhand, shoulder-width grip.', 'With a slight bend in the elbows, raise it to shoulder height.', 'Lower slowly without swinging.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Assisted_Dip', 'Assisted Dip', array['Assisted Dip Machine', 'Machine Assisted Dip']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'beginner', array['Set the assistance weight (more weight makes it easier) and kneel or stand on the pad, gripping the dip handles.', 'Lower until your upper arms are about level with the floor, elbows tucked and chest slightly forward.', 'Press back up to straight arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Single_Leg_Lying_Leg_Curl', 'Single-Leg Lying Leg Curl', '{}'::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Lie face down with one ankle under the pad, knee just off the edge of the bench.', 'Curl the pad toward your glutes, keeping your hips down.', 'Lower slowly. Finish all reps, then switch legs.']::text[], '{}'::text[], true, true, 'catalog')
